#include <vector>
#include <cstddef>
#include <cmath>
#include <algorithm>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Uses a Jacobi iterative method with OpenMP parallelization.
*/
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    x.assign(N, 0.0);
    if (N == 0) return;

    // Build diagonal (D) and off-diagonal COO lists for Jacobi.
    std::vector<double> diag(N, 0.0);
    std::vector<COOElement> off;
    off.reserve(A.size());

    for (const auto &e : A) {
        if (e.row >= N || e.column >= N) continue; // ignore out-of-range entries
        if (e.row == e.column) {
            diag[e.row] += e.value; // allow multiple diagonal entries
        } else {
            off.push_back(e);
        }
    }

    // Precompute CSR-like row pointers for the off-diagonal list to avoid atomics.
    // Sort by row then column.
    std::sort(off.begin(), off.end(),
              [](const COOElement& a, const COOElement& b) {
                  if (a.row != b.row) return a.row < b.row;
                  return a.column < b.column;
              });

    std::vector<size_t> rowPtr(N + 1, 0);
    for (const auto &e : off) {
        // e.row in [0, N)
        rowPtr[e.row + 1]++;
    }
    for (size_t i = 0; i < N; ++i) rowPtr[i + 1] += rowPtr[i];

    // Jacobi iteration
    std::vector<double> x_old(N, 0.0);

    const size_t maxIters = 10000;
    const double relTol = 1e-12;
    const double absTol = 1e-15;

    for (size_t iter = 0; iter < maxIters; ++iter) {
        x_old = x;

        double err2 = 0.0;
        double x2 = 0.0;

        #pragma omp parallel for reduction(+:err2,x2) schedule(static)
        for (size_t i = 0; i < N; ++i) {
            // Compute sum_{j!=i} A_ij * x_old[j] using per-row contiguous segment.
            double sum = 0.0;
            const size_t begin = rowPtr[i];
            const size_t end   = rowPtr[i + 1];
            for (size_t k = begin; k < end; ++k) {
                const auto &e = off[k];
                sum += e.value * x_old[e.column];
            }

            // Jacobi update: x_i = (b_i - sum_{j!=i} A_ij x_j) / A_ii
            // If diagonal is zero, leave as previous value (cannot update reliably).
            double xi = x_old[i];
            const double di = diag[i];
            if (di != 0.0) {
                xi = (b[i] - sum) / di;
            }
            x[i] = xi;

            const double diff = xi - x_old[i];
            err2 += diff * diff;
            x2   += xi * xi;
        }

        const double err = std::sqrt(err2);
        const double xn  = std::sqrt(x2);
        if (err <= std::max(absTol, relTol * xn)) {
            break;
        }
    }
}
